-- Built-in catalog metadata from https://github.com/legeling/awesome-codex-pet
-- Assets remain at their upstream source and retain their per-pet licenses.
ALTER TABLE pet_assets
  ADD COLUMN IF NOT EXISTS license TEXT NOT NULL DEFAULT '';

ALTER TABLE pet_user_preferences
  ADD COLUMN IF NOT EXISTS position_x DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS position_y DOUBLE PRECISION;

ALTER TABLE pet_user_preferences
  ALTER COLUMN anchor SET DEFAULT 'bottom-right';

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'pet_user_preferences_position_pair_check'
  ) THEN
    ALTER TABLE pet_user_preferences
      ADD CONSTRAINT pet_user_preferences_position_pair_check
      CHECK ((position_x IS NULL) = (position_y IS NULL));
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'pet_user_preferences_position_range_check'
  ) THEN
    ALTER TABLE pet_user_preferences
      ADD CONSTRAINT pet_user_preferences_position_range_check
      CHECK (position_x IS NULL OR (position_x BETWEEN 0 AND 1 AND position_y BETWEEN 0 AND 1));
  END IF;
END $$;

