  ('edef6e4d-159a-5171-a201-af77fab4d8a9'::uuid, NULL, 'longying--legeling', '胧萤', '融合猫头鹰的智慧轮廓、萤火虫般的暖金生命核心与虹彩自然科技材质的 AI 陪伴精灵，包含九组任务动画与完整的 16 方向环视动作。 | Author: Legeling | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/longying--legeling/spritesheet.webp', '6d594f8dcfa19f24ef7e3dd2381d14f75a60a4e146c312d7e54e9b7438eeca3a', 3088986, 1536, 2288, 'Non-commercial use only. Independently AI-generated community artwork based on a community request; no source pixels copied.'),
  ('ec771b3a-3c9c-58d0-943d-bd6dc6910638'::uuid, NULL, 'zichao-xiong--z-kzhang', '自嘲熊', 'Author: z.kzhang | Source: legeling/awesome-codex-pet', 1, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/zichao-xiong--z-kzhang/spritesheet.webp', '60b7174b85217c9073f076196a904778dfac7d1ff9204491765d3e37f143bde0', 1115570, 1536, 1872, 'Original AI-generated Codex pet based on a user-provided plush-bear reference. This is not an official Nagano/Jikochu Kuma asset and does not include copied logos, text, or original copyrighted artwork. Permission granted by the creator/uploader for inclusion in the awesome-codex-pet gallery.'),
  ('972c0927-d0c1-52c8-8285-4e8458101ac1'::uuid, NULL, 'feibi--vanfff', '菲比', 'A tiny blonde chibi companion with a white wide hat, purple eyes, blue hair clip, blue neck ribbon, and a slightly smug sticker-expression personality. | Author: vanfff | Source: legeling/awesome-codex-pet', 1, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/feibi--vanfff/spritesheet.webp', 'a9557926850b37c2b877c8777896366435c6b190f77876dff7d0ca296edca04a', 2102210, 1536, 1872, 'Unknown license; public Codex Pets upload; no explicit repository redistribution license was provided.'),
  ('6d0cba28-06c1-54f4-ba78-ab24cd78e708'::uuid, NULL, 'fujiwara-chika--klmklmnb', '藤原千花', 'A polished chibi sticker-style Chika Fujiwara pet with pink hair, her signature black bow, the Shuchiin school uniform, nine animation states, and 16 look directions. | Author: klmklmnb | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/fujiwara-chika--klmklmnb/spritesheet.webp', '030e73c1262af37b0a059a6fc7f95169903c285428387a1d95f8aca7a899a3e9', 1898760, 1536, 2288, 'Non-commercial use only. Unofficial independently AI-generated fan art submitted by klmklmnb for non-commercial repository redistribution; no official affiliation or endorsement. The original character and related intellectual property belong to their respective rights holders.'),
  ('baf63c4a-f555-5eaf-acb7-47eaabdd1382'::uuid, NULL, 'shinobu-kocho--wangfan002', '蝴蝶忍 / 蝴蝶忍 Q版 华丽动作', 'Author: wangfan002 | Source: legeling/awesome-codex-pet', 1, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/shinobu-kocho--wangfan002/spritesheet.webp', '4e8a87b5846791ce96cc028c41c52bad3eed75e89ddee70e2f30e43f5bbaa471', 1745172, 1536, 1872, 'Source author terms; personal non-commercial use only'),
  ('bdf5ab6b-68ec-5637-95bf-d1f1bae346c5'::uuid, NULL, 'bond-forger--legeling', '邦德·福杰', 'An independently AI-generated, non-commercial Bond Forger community pet with a huge fluffy white silhouette, small black ears, gentle sleepy eyes, black bow tie, nine standard animation states, and a complete 16-direction look loop. | Author: Legeling | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/bond-forger--legeling/spritesheet.webp', 'f6059c72fc0431d69721e69d63a2bbcf78be7f73df72c927fd3a4b10649f7cef', 1817320, 1536, 2288, 'Non-commercial use only. Independently AI-generated community fan art; no source pixels copied.'),
  ('3a6a353b-c890-51f2-8bc9-f0f1e59aceab'::uuid, NULL, 'jinmao--legeling', '金毛', '一只叼着网球、垂着大耳朵的奶油浅金色治愈系金毛幼犬，包含九组任务动画与完整的 16 方向环视动作。 | Author: Legeling | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/jinmao--legeling/spritesheet.webp', '1845ef8174a902f72fe269af9e22efff5c2cab9e0bb9aa330a0acb40569a74f6', 2033344, 1536, 2288, 'CC BY-NC 4.0'),
  ('cf6983d1-1a71-5dc4-8502-6c01fb6b5dc3'::uuid, NULL, 'wucanrou--ch', '金渐层（午餐肉）', '一只圆脸绿眼、粉鼻、金灰渐层短毛、体态敦实且尾尖较深的猫咪 Codex 宠物。 | Author: ch | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/wucanrou--ch/spritesheet.webp', '7b36138bcd6e3b1b6f5fb1c4783ffe26d3f9a76c71693a31f9fe1f2d9675f559', 2692738, 1536, 2288, 'Non-commercial use only.'),
  ('f5efad40-5e48-5b2f-b943-6079aff7935e'::uuid, NULL, 'youmu--ai-generated', '魂魄妖梦', '基于用户提供的 Gemini AI 生成参考图制作的魂魄妖梦 Codex 宠物；保留银发、绿色制服、佩刀与半灵特征，仅限非商业使用。 | Author: AI 生成（Gemini） | Source: legeling/awesome-codex-pet', 2, 'https://raw.githubusercontent.com/legeling/awesome-codex-pet/main/pets/youmu--ai-generated/spritesheet.webp', '40a483922c2f0dc52e224e9974b67a2569494b1c167bf170243071c71d980cc0', 2418486, 1536, 2288, 'Non-commercial use only. AI-generated with Gemini; the submitter confirms the right to include this asset in the repository.'),
